contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_dummy >= 0);

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (c.depositsCount() == beforeDeposits && address(c).balance == 0 && address(this).balance == beforeThisBalance + beforeBalance));
    }

    receive() external payable {}
}

