pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_dummy >= 0);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (c.depositsCount() == beforeDeposits && address(c).balance == 0 && address(this).balance == beforeThisBalance + beforeBalance));
    }

    function testFuzz_run(uint256 _dummy) public {
        _run(_dummy);
    }

    receive() external payable {}
}
